'use strict';
// 05.16: immutable weekly snapshots; actionable decisions always refer to the live company.
const DIGEST_BASE6={fresh,nextWeek,validateSave};
const DIGEST_CATEGORIES6={action:'Rozhodnutí',offers:'Nabídky',signed:'Smlouvy',people:'Lidé',operations:'Provoz',competition:'Soupeři',finance:'Platby a rezerva',news:'Události'};
const DIGEST_VIEWS6=['management','leadership','people','crises','business','markets','property','procurement','finance','stores','live','supply','roasters','bakery','rivals','season','board','organization','branding','coffee','city'];
function ensureDigest6(v){if(v.digest6===undefined)v.digest6={seen:Math.max(0,v.week-1),history:[]};return v;}
fresh=function(...args){return ensureDigest6(DIGEST_BASE6.fresh(...args));};ensureDigest6(state);
function collectDigest6(h,before){const previousNews=new Set(state.digest6.history.flatMap(h=>h.items.filter(x=>x.category==='news'||x.key.startsWith('resolved-poach-')).map(x=>x.key))),items=[],keys=new Set(),add=(category,key,title,text,view,target='',due=null,severity=1,pending=false)=>{if(keys.has(key)||previousNews.has(key)&&(category==='news'||key.startsWith('resolved-poach-')))return;keys.add(key);items.push({category,key,title:String(title).slice(0,120),text:String(text).slice(0,800),view,target:String(target).slice(0,80),due,severity,pending});},deadline=due=>due!==null&&due<=state.week?2:1;
 for(const o of state.offers){const rival=state.rivals.find(r=>r.id===o.rival);add('people','poach-'+o.id,'Konkurence oslovila '+o.name,(rival?.name||'Soupeř')+' nabízí '+money(o.salary)+'/týden. Rozhodnutí o dorovnání, loajalitě nebo odchodu čeká na tebe.','people',o.id,o.due,2,true);}
 for(const o of state.offerHistory.filter(o=>o.week>=h.week&&o.week<=state.week))add('people','resolved-poach-'+o.id,'Nabídka vyřízena: '+o.name,({match:'Mzda byla dorovnána.',stay:'Vyhodnocena loajalita člověka.',leave:'Odchod ke konkurenci.'})[o.choice]||'Nabídka byla vyhodnocena.','people',o.pid,null,1);
 for(const p of state.management5.proposals.filter(p=>p.status==='pending'))add('action','purchase-'+p.id,'Schválit nákup: '+ORIGINS[p.data.origin].name,money(p.quote.cost)+' · '+p.reason,'management',p.id,p.week+1,deadline(p.week+1),true);
 for(const p of state.empire.plans.filter(p=>p.status==='proposed'))add('action','plan-'+p.id,loc(p.store).name+' · návrh vedení',p.name+': '+p.action.title+'. Investice '+money(p.action.cost)+', navíc '+money(p.action.weekly)+'/týden.','leadership',p.id,p.due,deadline(p.due),true);
 for(const p of state.empire.stories)add('people','story-'+p.id,'Zpráva od '+p.name,({rest:'Potřebuje odpočinek od dlouhodobého přetížení.',ambition:'Chce jasnou cestu k povýšení.',craft:'Žádá prostor pro vývoj vlastní kávy.',mentoring:'Chce předávat zkušenosti dalším lidem.'})[p.type]||'Osobní rozhodnutí čeká na tebe.','leadership',p.id,p.due,deadline(p.due),true);
 for(const x of state.incidents)add('operations','crisis-'+x.id,x.title,x.details,'crises',x.id,x.due,deadline(x.due),true);
 for(const p of state.business5.proposals)add('offers','b2b-'+p.id,'Obchodní nabídka: '+businessClient5(p.client).name,p.kg+' kg/týden za '+money(p.price)+'/kg, '+p.weeks+' týdnů; splatnost '+p.terms+' týdnů. Nabídka nezaručuje přijetí, prověř aktuální podmínky.','business',p.id,p.due,deadline(p.due),true);
 for(const p of before.businessOffers.filter(p=>p.due<state.week&&!state.business5.proposals.some(x=>x.id===p.id)))add('offers','expired-b2b-'+p.id,'Vypršela nabídka: '+businessClient5(p.client).name,'Termín T'+p.due+' uplynul bez podpisu. O nových podmínkách je potřeba znovu jednat.','business',p.id,null,1);
 for(const c of state.contracts){if(c.business5?.started===h.week||!before.contracts.some(x=>x.id===c.id)||before.contracts.some(x=>x.id===c.id&&!x.last))add('signed','signed-'+c.id,'Nový odběr: '+c.name,c.kg+' kg/týden za '+money(c.price)+'/kg. Aktivní kontrakt.','business',c.id);if(c.remaining<=3)add('signed','renew-'+c.id,'Končí odběr: '+c.name,'Zbývá '+c.remaining+' týdnů. Obnovu prověř u odběratele; po skončení dál platí existující pohledávky.','business',c.id,state.week+c.remaining-1,1,true);if(c.last?.penalty||c.last?.delivered<c.kg*.8)add('signed','missed-'+c.id,'Nedodání: '+c.name,(c.last?.delivered||0)+' / '+c.kg+' kg, pokuta '+money(c.last?.penalty||0)+'. Prověř zásoby a kapacitu výroby.','business',c.id,null,2);}
 for(const c of before.contracts.filter(c=>!state.contracts.some(x=>x.id===c.id)))add('signed','ended-'+c.id,'Odběr skončil: '+c.name,'Kontrakt ukončil odběratel nebo doběhla sjednaná doba. Otevřené pohledávky zůstávají splatné.','business',c.id,null,1);
 for(const c of state.procurement5.contracts){if(c.start===h.week)add('signed','supplier-signed-'+c.id,'Sjednaný odběr zrn: '+SUPPLIERS5[c.supplier].name,ORIGINS[c.origin].name+' · '+c.kg+' kg/týden po '+money(c.unit)+'/kg. Pevná cena do T'+(c.end-1)+'.','procurement',c.id);if(['active','paused'].includes(c.status)&&c.end-state.week<=3)add('signed','supplier-end-'+c.id,'Končí cena zrn: '+SUPPLIERS5[c.supplier].name,ORIGINS[c.origin].name+' · odběr '+c.kg+' kg/týden. Pevné období končí před T'+c.end+'. Novou smlouvu prověř v nákupu.','procurement',c.id,c.end-1,1,true);}
 if(state.buyout)add('offers','buyout','Nabídka na odkup firmy',money(state.buyout.amount)+' od '+(state.rivals.find(r=>r.id===state.buyout.rival)?.name||'konkurence')+'. Přijetí ukončí tvoji kampaň.','rivals','',state.buyout.due,2,true);
 if(state.empire.partnership){const p=state.empire.partnership;add('offers','partnership','Partnerský odběr kávy',(state.rivals.find(r=>r.id===p.rival)?.name||'Soupeř')+' nabízí odběr '+p.kg+' kg za '+money(p.price)+'/kg.','markets','',p.due,deadline(p.due),true);}
 for(const a of state.auctions.filter(a=>!a.closed))add('offers','auction-'+a.id,'Aukce: '+loc(a.location).name,'Aktuální příhoz '+money(a.highest)+'. K nájemnímu právu potřebuješ kapitál na skutečné otevření.','rivals',a.id,a.due,deadline(a.due),true);
 for(const a of state.auctions.filter(a=>a.closedWeek===h.week))add('competition','auction-result-'+a.id,'Uzavřená aukce: '+loc(a.location).name,'Vítěz: '+(a.result==='player'?'Tvoje firma':state.rivals.find(r=>r.id===a.result)?.name||'Bez vítěze')+'.','rivals',a.id,null,1);
 for(const bill of state.procurement5.payables.filter(x=>x.paid===null&&x.due<=state.week+2))add('finance','payable-'+bill.id,'Platba: '+SUPPLIERS5[bill.supplier].name,money(bill.amount)+' dodavatelské faktury; splatnost T'+bill.due+'.','procurement',bill.id,bill.due,deadline(bill.due),true);
 for(const bill of state.business5.invoices.filter(x=>x.due<=state.week+2))add('finance','receivable-'+bill.id,'Příjem od odběratele',money(bill.amount)+' otevřené pohledávky; očekávaná úhrada T'+bill.due+'.','business',bill.id,bill.due,0);
 for(const s of state.stores.filter(s=>!s.franchise&&s.premises5.kind!=='owned'&&s.lease.due-state.week<=3))add('finance','lease-'+s.id,'Nájem: '+loc(s.id).name,'Pevná sazba končí v T'+s.lease.due+'. '+(s.premises5.autoRenew?'Obnova je povolená při krytí rezervy.':'Automatická obnova je vypnutá.'),'property',s.id,s.lease.due,1,true);
 if(state.cash<weeklyFixed()*3)add('finance','reserve','Nízká provozní rezerva',money(state.cash)+' dostupných peněz kryje přibližně '+numberDigest6(state.cash/Math.max(1,weeklyFixed()))+' týdnů fixních nákladů. Zásoby a investice potřebují další kapitál.','finance','',null,state.cash<weeklyFixed()?2:1);
 for(const o of state.procurement5.orders.filter(o=>o.status==='delayed'))add('operations','delay-'+o.id,'Zpožděná zrna: '+SUPPLIERS5[o.supplier].name,o.kg+' kg · aktuální příjezd T'+o.due+'.','procurement',o.id,o.due,2);
 for(const s of state.stores){if(s.last?.stockLost>0)add('operations','stock-'+s.id,loc(s.id).name+' · chyběla káva',s.last.stockLost+' hostů nemohlo být obslouženo kvůli zásobám.','supply',s.id,null,2);if(s.last?.profit<0)add('operations','loss-'+s.id,loc(s.id).name+' · ztrátová pobočka',money(s.last.profit)+' po plných provozních nákladech. Otevři výsledek a prověř menu, lidi a zásoby.','stores',s.id,null,1);}
 for(const r of state.management5.decisions.filter(d=>d.week===h.week&&(d.kind==='purchase'||d.changed||d.kind==='director')))add('action','decision-'+r.id,r.author+' · '+r.action,r.reason+(r.actual?.profit!==undefined?' Skutečný výsledek '+money(r.actual.profit)+'.':'')+(r.cost?' Zaplaceno '+money(r.cost)+'.':''),'management',r.id,null,0);
 for(const r of state.rivals){const old=before.rivals.find(x=>x.id===r.id);for(const id of r.stores.filter(id=>!old?.stores.includes(id)))add('competition','expansion-'+r.id+'-'+id,r.name+' otevřel '+loc(id).name,'Nová konkurence v '+loc(id).city+'. Prověř místní hosty, cenu a nabídku.','rivals',r.id,null,1);if(r.bankrupt&&!old?.bankrupt)add('competition','failed-'+r.id,r.name+' ukončil činnost','Soupeř je v platební neschopnosti.','rivals',r.id,null,0);}
 for(const l of state.logs.filter(l=>l.week>=h.week&&l.week<=state.week&&!l.text.startsWith('Týden ')).reverse())if(!items.some(x=>x.title===l.text))add('news','news-'+l.week+'-'+digestKey6(l.text+'|'+l.detail),l.text,l.detail,digestLogView6(l.text),'',null,0);
 items.sort((a,b)=>b.severity-a.severity||Number(b.pending)-Number(a.pending)||(a.due??1e9)-(b.due??1e9));return {week:h.week,profit:h.profit,revenue:h.revenue,cash:h.cash,cashChange:h.cashChange,cups:h.cups,debt:state.debt,reserve:Math.max(0,state.cash/Math.max(1,weeklyFixed())),over:state.over,milestone:state.win&&!before.win,items};
}
function digestKey6(text){let n=2166136261;for(const c of text)n=Math.imul(n^c.charCodeAt(0),16777619);return (n>>>0).toString(36);}
function digestLogView6(text){if(/Výpovědní|Ambice:|Kariérní|Nástupce|Jmenován nástupce|Zpráva z týmu|přebírá/i.test(text))return 'people';if(/Doručena káva|Objednána hotová káva/i.test(text))return 'supply';if(/konkurenc|Aukc|Soupeř|odkup firmy/i.test(text))return 'rivals';if(/talent|nastup|nastoup|mzda|odchod|přechází|Udržen|zůstává/i.test(text))return 'people';if(/Návrh vedení|Zpráva od|Osobní|povýš|školen/i.test(text))return 'leadership';if(/kontrakt|Jednání|Partnerství|Odběratel/i.test(text))return 'business';if(/nákup|dodavat|zrna/i.test(text))return 'procurement';if(/pražír|pražení|šarž/i.test(text))return 'roasters';if(/pekár|pečiv|jídla/i.test(text))return 'bakery';if(/kavárn|pobočk|provozu/i.test(text))return 'stores';return 'finance';}
function digestPending6(x){if(!x.pending)return false;const id=prefix=>x.key.slice(prefix.length);if(x.key.startsWith('poach-'))return state.offers.some(o=>o.id===id('poach-'));if(x.key.startsWith('purchase-'))return state.management5.proposals.some(p=>p.id===id('purchase-')&&p.status==='pending');if(x.key.startsWith('plan-'))return state.empire.plans.some(p=>p.id===id('plan-')&&p.status==='proposed');if(x.key.startsWith('story-'))return state.empire.stories.some(p=>p.id===id('story-'));if(x.key.startsWith('crisis-'))return state.incidents.some(p=>p.id===id('crisis-'));if(x.key.startsWith('b2b-'))return state.business5.proposals.some(p=>p.id===id('b2b-')&&p.due>=state.week);if(x.key.startsWith('renew-'))return state.contracts.some(p=>p.id===id('renew-')&&p.remaining<=3);if(x.key.startsWith('payable-'))return state.procurement5.payables.some(p=>p.id===id('payable-')&&p.paid===null);if(x.key.startsWith('auction-'))return state.auctions.some(p=>p.id===id('auction-')&&!p.closed);if(x.key==='buyout')return !!state.buyout;if(x.key==='partnership')return !!state.empire.partnership;if(x.key.startsWith('supplier-end-'))return state.procurement5.contracts.some(p=>p.id===id('supplier-end-')&&['active','paused'].includes(p.status)&&p.end-state.week<=3);if(x.key.startsWith('lease-'))return state.stores.some(s=>s.id===id('lease-')&&s.premises5.kind!=='owned'&&s.lease.due-state.week<=3);return false;}
function numberDigest6(n){return Math.max(0,n).toFixed(1);}
nextWeek=function(){const before={businessOffers:state.business5.proposals.map(p=>({...p})),contracts:state.contracts.map(c=>({...c})),rivals:state.rivals.map(r=>({id:r.id,stores:[...r.stores],bankrupt:r.bankrupt})),logs:[...state.logs],win:state.win};const h=DIGEST_BASE6.nextWeek();ensureDigest6(state);state.digest6.history.push(collectDigest6(h,before));state.digest6.history=state.digest6.history.slice(-13);return h;};
function weeklyDigest6(week=state.digest6.history.at(-1)?.week){return state.digest6.history.find(x=>x.week===week)||null;}
function acknowledgeDigest6(week){const h=weeklyDigest6(week);if(!h)throw Error('Shrnutí týdne není v archivu.');state.digest6.seen=Math.max(state.digest6.seen,week);}
validateSave=function(input){const v=DIGEST_BASE6.validateSave(input);ensureDigest6(v);const f=v.digest6,fail=()=>{throw Error('Soubor obsahuje neplatné týdenní shrnutí.');},n=(x,min=0)=>Number.isFinite(x)&&x>=min&&x<=1e12,int=(x,min=0,max=100000)=>Number.isInteger(x)&&x>=min&&x<=max,str=(x,max)=>typeof x==='string'&&x.length<=max;if(!f||!int(f.seen,0,v.week-1)||!Array.isArray(f.history)||f.history.length>13)fail();let week=0;for(const h of f.history){if(!int(h.week,week+1,v.week-1)||!['profit','cash','cashChange'].every(k=>n(h[k],-1e12))||!['revenue','cups','debt','reserve'].every(k=>n(h[k]))||typeof h.over!=='boolean'||typeof h.milestone!=='boolean'||!Array.isArray(h.items)||h.items.length>2000||new Set(h.items.map(x=>x.key)).size!==h.items.length)fail();week=h.week;for(const x of h.items)if(!Object.hasOwn(DIGEST_CATEGORIES6,x.category)||!str(x.key,160)||!str(x.title,120)||!str(x.text,800)||!DIGEST_VIEWS6.includes(x.view)||!str(x.target,80)||x.due!==null&&!int(x.due,1,100100)||!int(x.severity,0,2)||typeof x.pending!=='boolean')fail();}return v;};
